import { readFile, writeFile, access } from 'node:fs/promises';
import path from 'node:path';
const root = path.resolve(import.meta.dirname, '../..');
const jobs = JSON.parse(await readFile(path.join(root, 'scripts/pbr/asset-packs.json'), 'utf8'));
const entries = Array.isArray(jobs) ? jobs : [...jobs.assets, ...(jobs.installed ?? [])];
const relative = (p) =>
  './' + path.relative(path.join(root, 'src/rendering'), path.join(root, p)).replaceAll('\\', '/');
const lines = [
  '// Generated by scripts/pbr/update-runtime-catalog.mjs. Do not edit by hand.',
  'export interface AssetMaterialPack { sourcePath: string; source: string; dimensions: readonly [number, number]; maps: { diffuse: string; normal: string; surface: string; roughness?: string; metallic?: string; ao?: string; emissive?: string } }',
  'export const assetMaterialCatalog: readonly AssetMaterialPack[] = [',
];
for (const job of entries) {
  const pack = job.dimensions
    ? job
    : JSON.parse(await readFile(path.join(root, job.output, 'generation.json'), 'utf8'));
  const stem = path.basename(pack.source, '.png');
  let omissions = pack.omittedMaps ?? {};
  try {
    omissions =
      JSON.parse(await readFile(path.join(root, pack.output, `${stem}.material.json`), 'utf8'))
        .omittedMaps ?? {};
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  lines.push(
    `{ sourcePath: ${JSON.stringify(pack.source)}, source: new URL(${JSON.stringify(relative(pack.source))}, import.meta.url).href, dimensions: [${pack.dimensions}] as const, maps: {`,
  );
  for (const kind of ['diffuse', 'normal', 'roughness', 'metallic', 'ao', 'emissive', 'surface']) {
    if (omissions[kind] !== undefined) continue;
    await access(path.join(root, pack.output, `${stem}_${kind}.png`));
    lines.push(
      `${kind}: new URL(${JSON.stringify(relative(`${pack.output}/${stem}_${kind}.png`))}, import.meta.url).href,`,
    );
  }
  lines.push('} },');
}
lines.push('] as const;');
await writeFile(
  path.join(root, 'src/rendering/asset-material-catalog.ts'),
  lines.join('\n') + '\n',
);
